const TOPIC_SCREEN={'quick-start':'overview',waveforms:'waveforms',mapping:'mapping',components:'components',counts:'counts',characteristics:'curves',interpolation:'interpolation','zero-floor':'origin',gates:'gates',switching:'gates',passives:'passives',thermal:'thermal',results:'results',debug:'debug',sensitivity:'sensitivity',troubleshooting:'checks',saving:'saving',limits:'help','mosfet-losses':'point','diode-losses':'diode','capacitor-losses':'passives','inductor-losses':'core','numerical-methods':'thermal'};
const text=(x,y,s,size=17,fill='#e4edf3',extra='')=>`<text x="${x}" y="${y}" fill="${fill}" font-family="system-ui,sans-serif" font-size="${size}" ${extra}>${e(s)}</text>`;
const rect=(x,y,w,h,fill='#19222d',stroke='#34434d')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${fill}" ${stroke?`stroke="${stroke}"`:''}/>`;
function wrapLines(value,max){const words=String(value).split(' '),lines=[];let line='';for(const word of words){if(line&&line.length+word.length+1>max){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return lines;}
function panelSVG(p,x,y,w,h,index){let s=rect(x,y,w,h)+`<circle cx="${x+20}" cy="${y+25}" r="12" fill="#c6f278"/>`+text(x+20,y+31,index,17,'#10171e','text-anchor="middle"')+text(x+40,y+31,p.title,Math.max(14,Math.min(17,Math.floor((w-58)/(p.title.length*.6)))));
 if(p.kind==='fields'){let baseline=y+60;for(const r of p.rows){const size=r.value.length>43?14:16,labelLines=wrapLines(r.label,Math.floor((w-32)/(14*.6))),valueLines=wrapLines(r.value,Math.floor((w-32)/(size*.6)));for(const label of labelLines){s+=text(x+16,baseline,label,14,'#a4b5c2');baseline+=17;}baseline+=4;for(const value of valueLines){s+=text(x+16,baseline,value,size);baseline+=18;}baseline+=7;}return s;}
 if(p.kind==='combined'){const base=x+118,width=w-172;for(let j=0;j<2;j++){const yy=y+88+j*96,total=j?15:13,items=j?[{n:'Q1',v:7,c:[.55,.3,.15]},{n:'Q2',v:5,c:[.55,.3,.15]},{n:'L1',v:2,c:[0,0,1]},{n:'C1',v:1,c:[0,0,1]}]:[{n:'Q1',v:6,c:[.7,.2,.1]},{n:'Q2',v:4,c:[.7,.2,.1]},{n:'L1',v:2,c:[0,0,1]},{n:'C1',v:1,c:[0,0,1]}];s+=text(x+14,yy+16,'Alternative '+(j?'B':'A'),15);let off=0;for(const it of items){const ww=width*it.v/15;let cOff=0;it.c.forEach((ratio,k)=>{if(ratio){s+=`<rect x="${base+off+cOff}" y="${yy}" width="${ww*ratio}" height="26" fill="${['#c6f278','#f6b56d','#79d8c1'][k]}"/>`;cOff+=ww*ratio;}});s+=`<rect x="${base+off}" y="${yy+30}" width="${ww}" height="24" fill="#263441"/>`+text(base+off+ww/2,yy+47,it.n,13,'#e4edf3','text-anchor="middle"');off+=ww;}s+=text(base+off+5,yy+19,total+' W',13);}s+=text(x+18,y+h-23,'Hover: watts + share   ·   Click: inspect component',15,'#a4b5c2');return s;}
 if(p.kind==='curve'){s+=`<path d="M${x+55} ${y+70}V${y+h-55}H${x+w-28}" stroke="#a4b5c2" fill="none"/><path d="M${x+55} ${y+h-90}L${x+w-35} ${y+90}" stroke="#c6f278" fill="none" stroke-width="3"/><path d="M${x+55} ${y+h-65}L${x+w-35} ${y+145}" stroke="#82bfff" fill="none" stroke-width="3"/><circle cx="${x+250}" cy="${y+172}" r="7" fill="#f975f0"/>`;s+=text(x+16,y+62,'Characteristic output',14,'#a4b5c2')+text(x+w/2,y+h-22,'Characteristic input',15,'#a4b5c2','text-anchor="middle"')+text(x+75,y+106,'Reference family',15,'#c6f278')+text(x+265,y+168,'Query',15,'#f975f0');return s;}
 if(p.kind==='traces'){const start=x+115,end=x+w-24,cursor=x+w*.62;for(let j=0;j<3;j++){const yy=y+95+j*65;s+=text(x+15,yy+8,['Current [A]','Voltage [V]','Gate [V]'][j],14,'#a4b5c2')+`<path d="M${start} ${yy}H${start+75}V${yy-23}H${end-55}V${yy}H${end}" stroke="${['#c6f278','#82bfff','#f6b56d'][j]}" fill="none" stroke-width="2"/>`;}s+=`<path d="M${cursor} ${y+65}V${y+h-45}" stroke="#f975f0" stroke-dasharray="5 4"/>`+text(x+w/2,y+h-20,'Shared time cursor · example traces',15,'#a4b5c2','text-anchor="middle"');return s;}
 return s;}
export function screenGuideKey(topic){return TOPIC_SCREEN[topic];}
export function screenGuideSVG(key){const g=SCREEN_GUIDES[key];if(!g)return '';let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 560" role="img" aria-label="Screen guide illustration: ${e(g.title)}"><title>${e(g.title)} — annotated illustration</title><desc>${e(g.notes.join(' '))} This is a schematic illustration of current controls with synthetic example values, not a browser screenshot.</desc>`+rect(1,1,958,558,'#10171e','#34434d')+rect(12,12,146,536,'#141e28',null)+text(27,44,'LOSS LAB',20,'#c6f278')+text(182,43,g.page,25)+text(182,72,'Annotated screen illustration · synthetic example',15,'#a4b5c2')+rect(754,24,78,35,'#263441')+text(766,47,'Help ?',15)+rect(841,24,100,35,'#c6f278',null)+text(851,47,'Run analysis',14,'#10171e');const nav=['Study overview','Waveforms','Components','Check inputs','Results','Documentation'];nav.forEach((n,j)=>s+=text(25,111+j*43,n,14,n.startsWith(g.page.split(' ')[0])?'#c6f278':'#a4b5c2'));s+=panelSVG(g.panels[0],182,101,462,367,1)+panelSVG(g.panels[1],658,101,286,172,2)+panelSVG(g.panels[2],658,287,286,181,3)+text(184,508,'Numbered callouts below explain the workflow; exact layout can change.',15,'#a4b5c2')+text(184,536,'ILLUSTRATION — not a captured tool screen',14,'#c6f278');return s+'</svg>';}
export function screenGuideHTML(topic){const key=TOPIC_SCREEN[topic],g=SCREEN_GUIDES[key];if(!g)return '';return `<figure class="doc-screen-guide"><figcaption><strong>Screen guide: ${e(g.title)}</strong></figcaption><p class="caption">Annotated UI illustration using current control names and synthetic examples. It is not a browser screenshot. On small screens, scroll the illustration sideways.</p><div class="doc-screen-scroll">${screenGuideSVG(key)}</div><ol>${g.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ol></figure>`;}
